static enum MHD_Result dispatch(void *cls, struct MHD_Connection *c,
                                const char *url, const char *method,
                                const char *version, const char *upload,
                                size_t *upload_size, void **con_cls)
{
    if (!authorized(c))                    /* shared chain, may short-circuit */
        return MHD_queue_basic_auth_fail_response(c, "app", deny_page());
    for (const struct route *r = routes; r->handler; r++)
        if (strcmp(r->method, method) == 0 && match(r->pattern, url))
            return r->handler(c, cls);     /* dispatcher */
    return MHD_queue_response(c, MHD_HTTP_NOT_FOUND, not_found_page());
}
